using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
public static class SetupClosedHangarGrain {
 public static string Main(){if(EditorApplication.isPlaying)throw new Exception("Edit mode required");var root=GameObject.Find("New_Map").transform;var exp=root.Find("11_Five_Hangar_Farm");var piles=UnityEngine.Object.FindObjectsByType<GrainPile>(FindObjectsInactive.Include,FindObjectsSortMode.None).Where(p=>p.gameObject.scene==root.gameObject.scene).ToArray();if(piles.Length!=5)throw new Exception("Unexpected pile count "+piles.Length);EditorSceneManager.SaveScene(root.gameObject.scene,"Temp/FiveHangars/Gameplay.before-closed-grain-culling.unity",true);
  for(int i=1;i<=5;i++){var owner=i==1?root.Find("01_Modular_Hangar"):exp.Cast<Transform>().Single(t=>t.name.StartsWith("Hangar "+i+" -"));var pile=i==1?piles.Single(p=>!p.name.StartsWith("Hangar ")):piles.Single(p=>p.name.StartsWith("Hangar "+i+" -"));var state=owner.GetComponent<HangarGrainVisibility>();if(!state)state=Undo.AddComponent<HangarGrainVisibility>(owner.gameObject);var so=new SerializedObject(state);so.FindProperty("hangarOpen").boolValue=i==1;so.FindProperty("grainRoot").objectReferenceValue=pile.gameObject;so.ApplyModifiedProperties();Undo.RecordObject(pile.gameObject,"Set closed hangar grain visibility");state.ApplyState();EditorUtility.SetDirty(pile.gameObject);}
  AssetDatabase.StartAssetEditing();try{foreach(var guid in AssetDatabase.FindAssets("t:Mesh",new[]{"Assets/NewMap/FiveHangars/HillTrees"})){var path=AssetDatabase.GUIDToAssetPath(guid);var m=AssetDatabase.LoadAssetAtPath<Mesh>(path);string name=Path.GetFileNameWithoutExtension(path);if(m.name==name)continue;m.name=name;EditorUtility.SetDirty(m);}}finally{AssetDatabase.StopAssetEditing();}AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(root.gameObject.scene);EditorSceneManager.SaveScene(root.gameObject.scene);return "Hangar 1 grain active; hangars 2-5 grain GameObjects inactive, with HangarGrainVisibility state bindings. Grove asset names normalized without changing GUIDs.";
 }
}

